GROUP_ANAGRAMS:
from collections import defaultdict
class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        g = defaultdict(list)
        for s in strs:
            g[''.join(sorted(s))].append(s)
        return list(g.values())

